+ 30: /**
+ 31:  * <div>
+ 32:  * Checks if the multi-line bock comments has
+ 33:  * <a href="https://www.oracle.com/java/technologies/javase/codeconventions-comments.html">
+ 34:  * leading asterisks</a> on each line.
+ 35:  * </div>
+ 36:  *
+ 37:  * <p>
+ 38:  * Every line in multi-line comment should have leading asterisk including blank line.
+ 39:  * </p>
+ 40:  *
+ 41:  * @since 13.8.0
+ 42:  */
+ 43: @StatelessCheck
+ 44: public class MultilineCommentLeadingAsteriskPresenceCheck extends AbstractCheck {
+ 45: 
+ 46:     /**
+ 47:      * A key is pointing to the warning message text in "messages.properties"
+ 48:      * file.
+ 49:      */
+ 50:     public static final String MSG_MISSING_ASTERISK = "multiline.comment.missing.asterisk";
+ 51: 
+ 52:     @Override
+ 53:     public int[] getRequiredTokens() {
+ 54:         return new int[] {
+ 55:             TokenTypes.BLOCK_COMMENT_BEGIN,
+ 56:         };
+ 57:     }
+ 58: 
+ 59:     @Override
+ 60:     public int[] getAcceptableTokens() {
+ 61:         return getRequiredTokens();
+ 62:     }
+ 63: 
+ 64:     @Override
+ 65:     public int[] getDefaultTokens() {
+ 66:         return getRequiredTokens();
+ 67:     }
+ 68: 
+ 69:     @Override
+ 70:     public boolean isCommentNodesRequired() {
+ 71:         return true;
+ 72:     }
+ 73: 
+ 74:     @Override
+ 75:     public void visitToken(DetailAST ast) {
+ 76:         if (!JavadocUtil.isJavadocComment(ast)) {
+ 77:             final String commentText = JavadocUtil.getBlockCommentContent(ast);
+ 78:             int lineNumber = ast.getLineNo();
+ 79:             final int commentEndLineNumber = ast.getLastChild().getLineNo();
+ 80:             final List<String> lines = commentText.lines().toList();
+ 81:             for (int cur = 1; cur < lines.size(); cur++) {
+ 82:                 lineNumber++;
+ 83:                 final String line = lines.get(cur).trim();
+ 84:                 // is block comment end
+ 85:                 if (lineNumber == commentEndLineNumber && line.isEmpty()) {
+ 86:                     continue;
+ 87:                 }
+ 88:                 if (!line.startsWith("*")) {
+ 89:                     log(lineNumber, MSG_MISSING_ASTERISK);
+ 90:                 }
+ 91:             }
+ 92:         }
+ 93:     }
+ 94: }

